WITH grp AS (
  SELECT id FROM public.institution_groups WHERE name = 'Caja La Araucana' LIMIT 1
), upd AS (
  UPDATE public.institutions i
  SET
    institution_name = 'CAJA LA ARAUCANA',
    zone_id = 5,
    region_id = 17,
    comuna_id = 30,
    submission_method_id = 1,
    validation_status_id = 1,
    observation = NULL,
    active = true,
    updated_at = now(),
    modified_by = 'import_xlsx',
    institution_group_id = (SELECT id FROM grp)
  WHERE lower(trim(i.email)) = lower(trim('cbarria@laaraucana.cl'))
  RETURNING i.id
)
